const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

/**
 * Parses an election from the raw text of standard input. Returns the
 * declared candidates in declaration order and the ballots in the order
 * they appeared, with each ballot's count already converted to a BigInt.
 * Throws a ValidationError describing the first malformed line, or
 * `no candidates` if the input never declares the candidates field.
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidatesDeclared = false
  let candidateOrder = []
  let candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const tokens = line.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw new ValidationError('candidates must be declared once, before any ballot', lineNum)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        throw new ValidationError('expected candidates <name>...', lineNum)
      }
      const seen = new Set()
      for (const name of names) {
        if (!NAME_PATTERN.test(name)) {
          throw new ValidationError(`invalid candidate name ${name}`, lineNum)
        }
        if (seen.has(name)) {
          throw new ValidationError(`candidate ${name} is declared twice`, lineNum)
        }
        seen.add(name)
      }
      candidatesDeclared = true
      candidateOrder = names
      candidateSet = seen
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new ValidationError('candidates must be declared once, before any ballot', lineNum)
      }
      const rest = tokens.slice(1)
      if (rest.length < 2) {
        throw new ValidationError('expected ballot <count> <candidate>...', lineNum)
      }
      const [countStr, ...names] = rest
      if (!COUNT_PATTERN.test(countStr)) {
        throw new ValidationError('count must be a positive integer', lineNum)
      }
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ValidationError(`unknown candidate ${name}`, lineNum)
        }
        if (seen.has(name)) {
          throw new ValidationError(`candidate ${name} is repeated`, lineNum)
        }
        seen.add(name)
      }
      ballots.push({ count: BigInt(countStr), names })
    } else {
      throw new ValidationError(`unknown directive ${directive}`, lineNum)
    }
  }

  if (!candidatesDeclared) {
    throw new ValidationError('no candidates', null)
  }

  return { candidates: candidateOrder, ballots }
}
"}

