 * Runs the instant-runoff count for a parsed election. Returns the list of
 * rounds counted, each holding the vote map for every candidate still
 * continuing at the start of that round, the number of exhausted ballots,
 * and the name eliminated at the end of the round (null for the final
 * round, which ends the election instead), plus the overall winner
 * (null when no candidate ever reached a majority).
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0n)

    let exhausted = 0n
    for (const ballot of ballots) {
      const target = ballot.names.find((name) => continuing.has(name))
      if (target === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(target, votes.get(target) + ballot.count)
      }
    }
    history.push(votes)

    let activeTotal = 0n
    for (const v of votes.values()) activeTotal += v

    let roundWinner = null
    if (activeTotal > 0n) {
      for (const [name, v] of votes) {
        if (v * 2n > activeTotal) {
          roundWinner = name
          break
        }
      }
    }

    if (activeTotal === 0n || roundWinner !== null) {
      rounds.push({ votes, exhausted, eliminated: null })
      winner = roundWinner
      break
    }

    let minVotes = null
    for (const v of votes.values()) {
      if (minVotes === null || v < minVotes) minVotes = v
    }
    const tied = [...continuing].filter((name) => votes.get(name) === minVotes)
    const eliminated = tied.length === 1 ? tied[0] : breakTie(tied, history)
    continuing.delete(eliminated)
    rounds.push({ votes, exhausted, eliminated })
  }

  return { rounds, winner }
}

/**
 * Picks which of the tied-for-fewest candidates to eliminate by comparing
 * their vote counts round by round from the first round, narrowing to
 * whichever had fewest at the first round that separates them and
 * restarting the comparison from the first round among the survivors.
 * When no round separates them, the name that sorts last by code point
 * is eliminated.
 */
function breakTie(tied, history) {
  let candidates = tied.slice()

  while (true) {
    let narrowed = false
    for (const roundVotes of history) {
      const values = candidates.map((name) => roundVotes.get(name))
      if (values.every((v) => v === values[0])) continue

      let minVotes = values[0]
      for (const v of values) if (v < minVotes) minVotes = v
      candidates = candidates.filter((name) => roundVotes.get(name) === minVotes)
      narrowed = true
      break
    }
    if (!narrowed || candidates.length === 1) break
  }

  if (candidates.length === 1) return candidates[0]
  candidates.sort()
  return candidates[candidates.length - 1]
}
"}

