 */

import { parseElection } from './parser.js'
import { runElection } from './election.js'
import { formatRounds, formatTally } from './format.js'
import { ValidationError } from './errors.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    fail('usage: cli.js rounds|tally')
  }

  const input = readStdin()

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ValidationError) {
      fail(err.line !== null ? `line ${err.line}: ${err.message}` : err.message)
    }
    throw err
  }

  const result = runElection(election.candidates, election.ballots)
  const output = mode === 'rounds' ? formatRounds(result) : formatTally(result)
  process.stdout.write(output)
}

main()
"}

